'use strict'

import resource from '../../resource'
import { NES_PIXEL, TILE_WIDTH, TILE_HEIGHT, DIRECTION_EAST, DIRECTION_WEST, DIRECTION_NORTH, DIRECTION_SOUTH } from '../../constant'
import { Enemy, DIRECTION_VECTORS, drawImage } from './common'

// The blade traps of the corners of a room, read in the ROM (object $49, bank 1 $A34A; the four made by $4A).
// Waiting, a trap rushes at Link when he is less than 14 NES pixels from its line or its column, the ways its
// corner lets it ($A344: away from the walls), at $70 (1.75 NES pixel a frame), until it is less than 5 pixels
// from the middle of the room (x = $78, y = $90); then it goes back at $20 (0.5 pixel a frame) to where it started,
// and waits again. Nothing hurts it; it takes a heart from Link, and the room is cleared without killing it
const TRAP = { life: Infinity, contactDamage: 1 }
const RUSH_SPEED = 0x70
const BACK_SPEED = 0x20
const PER_PIXEL = 0x40
const IN_LINE = 14 * NES_PIXEL
const NEAR_MIDDLE = 5 * NES_PIXEL
const NES_TOP = 0x3d
const MIDDLE = { x: 0x78 * NES_PIXEL, y: (0x90 - NES_TOP) * NES_PIXEL }
// The four corners of the room, in the order of their places (1 to 4), and the ways each may go; $49 makes 6 traps
export const TRAP_CORNERS = [
  { column: 2, line: 2, ways: [DIRECTION_EAST, DIRECTION_SOUTH] },
  { column: 2, line: 8, ways: [DIRECTION_EAST, DIRECTION_NORTH] },
  { column: 13, line: 2, ways: [DIRECTION_WEST, DIRECTION_SOUTH] },
  { column: 13, line: 8, ways: [DIRECTION_WEST, DIRECTION_NORTH] },
  // Of $49 (measured in $02 of level 4): two more in the middle line, at x $40 and $B0, rushing to the middle
  { column: 4, line: 5, ways: [DIRECTION_EAST] },
  { column: 11, line: 5, ways: [DIRECTION_WEST] }
]
const STATE_READY = 'ready'
const STATE_RUSHING = 'rushing'
const STATE_BACK = 'back'

export class BladeTrap extends Enemy {
  constructor (type, x, y, ways, random = Math.random) {
    super(type, x, y, TRAP, random)
    this.ways = ways
    this.home = { x, y }
    this.direction = undefined
    this.fraction = 0
  }

  get isVulnerable () {
    return false
  }

  get mustDie () {
    return false
  }

  // Out of its cloud
  start (map) {
    this.setState(STATE_READY)
  }

  // In line with Link, the way to him, if its corner lets it
  aim (link) {
    let direction
    if (Math.abs(link.y - this.y) < IN_LINE && link.x !== this.x) {
      direction = link.x > this.x ? DIRECTION_EAST : DIRECTION_WEST
    } else if (Math.abs(link.x - this.x) < IN_LINE && link.y !== this.y) {
      direction = link.y > this.y ? DIRECTION_SOUTH : DIRECTION_NORTH
    }
    return this.ways.includes(direction) ? direction : undefined
  }

  // NES pixels this frame at that speed
  pixels (speed) {
    this.fraction += speed
    const pixels = Math.floor(this.fraction / PER_PIXEL)
    this.fraction %= PER_PIXEL
    return pixels
  }

  act (map, link) {
    switch (this.state) {
      case STATE_READY: {
        const direction = this.aim(link)
        if (direction) {
          this.direction = direction
          this.fraction = 0
          this.setState(STATE_RUSHING)
        }
        break
      }
      case STATE_RUSHING: {
        const [dx, dy] = DIRECTION_VECTORS[this.direction]
        const pixels = this.pixels(RUSH_SPEED)
        this.x += dx * pixels * NES_PIXEL
        this.y += dy * pixels * NES_PIXEL
        const fromMiddle = dx !== 0 ? this.x - map.x - MIDDLE.x : this.y - map.y - MIDDLE.y
        if (Math.abs(fromMiddle) < NEAR_MIDDLE) {
          this.setState(STATE_BACK)
        }
        break
      }
      case STATE_BACK: {
        const [dx, dy] = DIRECTION_VECTORS[this.direction]
        for (let i = this.pixels(BACK_SPEED); i > 0; i--) {
          this.x -= dx * NES_PIXEL
          this.y -= dy * NES_PIXEL
          if (this.x === this.home.x && this.y === this.home.y) {
            this.setState(STATE_READY)
            break
          }
        }
        break
      }
    }
  }

  drawBody (context) {
    drawImage(context, resource.getSprite('blade_trap_move'), 0, this.x, this.y, TILE_WIDTH, TILE_HEIGHT)
  }
}
