'use strict'

import InputManager from '../service/input-manager'
import resource from '../resource'
import clock from '../service/clock'
import textManager from '../service/text-manager'
import { listenMenuKeys } from './menu-keys'
import { NES_PIXEL, SPRITE_TEXT_COLOR_WHITE, SPRITE_TEXT_COLOR_RED } from '../constant'

const FRAME = 1000 / 60
// As in the ROM (mode $08, bank 5 $8AF4; name table measured), in NES pixels, the 8 lines at the top of the screen
// not shown: the choices at column 10 of lines 10, 13 and 16; the heart (sprite $F2, colour $16) at x $40, y $4F +
// $18 × choice, an 8 × 16 sprite drawn a line under its y
const SCREEN_TOP = 8
const TEXT_X = 80
const TEXT_Y = 80
const LINE_STEP = 24
const HEART_X = 0x40
const HEART_Y = 0x4f
const TILE = 8
// Start: the choice flashes red ($29 from $40: red while its bit 2 is set, attribute $23D2 + line) until frame 63,
// then the game does it (measured: CONTINUE at frame 63, SAVE and RETRY at 64)
export const CHOSEN_FRAMES = 63
const FLASH_FROM = 0x40
const FLASH_BIT = 4

// After the game over, or with Up and A in the inventory: continue (from the start, with all the items), save (the
// game kept in its place, then the choice of the game) or retry (the choice of the game, nothing kept). Select moves
// the heart, Start chooses
class GameOverMenu {
  // options: [{ label, choose }]; wait(frames): a promise of that many frames of the game
  constructor (options, wait) {
    this.options = options
    this.wait = wait
    this.selection = 0
    this.chosenAt = undefined
    this.stopListening = listenMenuKeys({
      [InputManager.ACTION_SELECT]: () => this.move(1),
      [InputManager.ACTION_START]: () => this.choose()
    })
  }

  move (delta) {
    this.selection = (this.selection + delta + this.options.length) % this.options.length
  }

  async choose () {
    this.dispose()
    this.chosenAt = clock.now
    await this.wait(CHOSEN_FRAMES)
    this.options[this.selection].choose()
  }

  dispose () {
    this.stopListening?.()
    this.stopListening = undefined
  }

  // The choice made, red or white
  flashing () {
    if (this.chosenAt === undefined) {
      return false
    }
    const frame = Math.floor((clock.now - this.chosenAt) / FRAME)
    return ((FLASH_FROM - frame) & FLASH_BIT) !== 0
  }

  draw (context, width, height) {
    context.fillStyle = 'black'
    context.fillRect(0, 0, width, height)
    this.options.forEach((option, i) => {
      const colour = i === this.selection && this.flashing() ? SPRITE_TEXT_COLOR_RED : SPRITE_TEXT_COLOR_WHITE
      textManager.drawLine(context, option.label, colour, TEXT_X * NES_PIXEL, (TEXT_Y + i * LINE_STEP - SCREEN_TOP) * NES_PIXEL)
    })
    const y = HEART_Y + this.selection * LINE_STEP + 1
    resource.getSprite('select_heart_red')?.draw(context, HEART_X * NES_PIXEL, (y - SCREEN_TOP) * NES_PIXEL, TILE * NES_PIXEL, TILE * NES_PIXEL)
  }
}

export { GameOverMenu }
