'use strict'

import resource from '../resource'
import clock from '../service/clock'
import worldManager from '../service/world-manager'
import textManager from '../service/text-manager'
import { worldMinimap } from './world-minimap'
import { SPRITE_TEXT_COLOR_RED, SPRITE_TEXT_COLOR_WHITE, NES_PIXEL, MAP_TYPES_LEVELS, MAP_TYPE_WORLD, TILE_WIDTH, TILE_HEIGHT, TILES_PER_LINE, TILES_PER_COLUMN } from '../constant'

// Options of the page (see display.js): the surface drawn on the map instead of the gray of the ROM
export const topMenuOptions = { detailedMap: false }

// The top menu of the original, at the places of its tiles in the ROM (name table, measured), in NES pixels, doubled
// for the display. Its first 16 lines are empty: the menu shown starts at y = 16
const SCALE = NES_PIXEL
const TOP = 16
const TILE = 8 * SCALE

// The map, from x = 16, y = 24 (8 × 4 tiles). At the surface, gray (tile $F5), a screen is 4 × 4 pixels and Link a
// dot of 3 pixels (sprite $3E, colour $29) at x = 16 + column × 4 + 1, y = 24 + line × 4 (bank 1 $AA4E). In a level,
// a room is 7 × 3 pixels (tiles $67, $FB, $FF: two rooms a tile, colour $12), 8 pixels wide and 4 high, drawn only
// with the map of the level; the dot of Link is in it, 2 pixels from its left, but not under the stairs
const MAP_X = 16
const MAP_Y = 24
const MAP_COLUMNS = 8
const MAP_LINES = 4
const SCREEN_SIZE = 4
const SCREEN_DOT = 1
const ROOM_WIDTH = 8
const ROOM_HEIGHT = 4
const ROOM_DOT = 2

// With the compass, the dot of the room of the piece of the Triforce, red 16 frames, then 16 frames in the sprite
// palette 3 of the level, its colour from when the piece is taken (frame counter $15, bank 1 $AA97)
const COMPASS_FRAMES = 32
const COMPASS_RED_FRAMES = 16
const FRAME = 1000 / 60

// The counters: the tile of the item at x = 88, then « X » and the number, or the number alone from 100 (y = 24,
// 40, 48)
const COUNTER_ICON_X = 88
const COUNTER_X = 96
const COUNTERS = [['rupee', inventory => inventory.rupees, 24], ['key', inventory => inventory.keys, 40], ['bomb', inventory => inventory.bombs, 48]]

// The frames of B and A, 3 × 4 tiles from x = 120 and 144, y = 24; their item (8 pixels wide) at x = 128 and 152, y = 32
const FRAMES = [['b', 120, 'itemB'], ['a', 144, 'itemA']]
const FRAME_Y = 24
const FRAME_ITEM_Y = 32

// « -LIFE- » at x = 184, y = 24; the hearts from x = 176, 8 on the line y = 48, then on y = 40
const LIFE_X = 184
const HEARTS_X = 176
const HEARTS_Y = 48
const HEARTS_PER_LINE = 8

// The text of a counter
export function counterText (count) {
  return count < 100 ? `x${count}` : `${count}`
}

// The palette of the dot of the compass: red, then the one of the level (of level 1 by default); that one alone once
// the piece is taken
export function compassPalette (frame, taken, type = MAP_TYPES_LEVELS[0]) {
  return !taken && frame % COMPASS_FRAMES < COMPASS_RED_FRAMES ? 'compass_red' : `compass_${type}`
}

// Where a room of a level is on the map (NES pixels): its place in the grid of the level, whose rooms are at their
// column on this map (see tools/levels/build.js)
export function roomPlace (room) {
  return { x: MAP_X + room.column * ROOM_WIDTH, y: MAP_Y + room.line * ROOM_HEIGHT }
}

// On the detailed map, the dot of Link (3 NES pixels) centred where he is, a screen being 4 × 4 pixels of the map
const DOT_HALF = 1.5
export function linkOnMap (link) {
  const centre = (position, size, tiles) => (position + size / 2) * SCREEN_SIZE / (tiles * size)
  return {
    x: MAP_X + centre(link.x, TILE_WIDTH, TILES_PER_LINE) - DOT_HALF,
    y: MAP_Y + centre(link.y, TILE_HEIGHT, TILES_PER_COLUMN) - DOT_HALF
  }
}

class TopMenu {
  constructor (link) {
    this.link = link
  }

  drawTile (context, name, x, y) {
    resource.getSprite(name)?.draw(context, x * SCALE, (y - TOP) * SCALE, TILE, TILE)
  }

  drawText (context, text, color, x, y) {
    textManager.drawLine(context, text, color, x * SCALE, (y - TOP) * SCALE)
  }

  drawSurfaceMap (context, map) {
    const detailed = topMenuOptions.detailedMap && worldMinimap()
    if (detailed) {
      this.drawDetailedMap(context, detailed, map)
      return
    }
    for (let column = 0; column < MAP_COLUMNS; column++) {
      for (let line = 0; line < MAP_LINES; line++) {
        this.drawTile(context, 'menu_map_surface', MAP_X + column * 8, MAP_Y + line * 8)
      }
    }
    this.drawTile(context, 'menu_map_dot_link', MAP_X + map.column * SCREEN_SIZE + SCREEN_DOT, MAP_Y + map.line * SCREEN_SIZE)
  }

  // The surface drawn small (not in the ROM), and Link's dot where he is on it; in a cave, on its screen
  drawDetailedMap (context, image, map) {
    context.save()
    context.imageSmoothingEnabled = true
    context.imageSmoothingQuality = 'high'
    context.drawImage(image, MAP_X * SCALE, (MAP_Y - TOP) * SCALE, MAP_COLUMNS * 8 * SCALE, MAP_LINES * 8 * SCALE)
    context.restore()
    const { x, y } = map.type === MAP_TYPE_WORLD ? linkOnMap(this.link) : { x: MAP_X + map.column * SCREEN_SIZE + SCREEN_DOT, y: MAP_Y + map.line * SCREEN_SIZE }
    this.drawTile(context, 'menu_map_dot_link', x, y)
  }

  drawLevelMap (context, map, level) {
    const inventory = this.link.inventory
    this.drawText(context, `level-${level}`, SPRITE_TEXT_COLOR_WHITE, MAP_X, 16)
    const rooms = worldManager[map.type].flat().filter(room => room?.room)
    if (inventory.maps.includes(level)) {
      for (const room of rooms) {
        const { x, y } = roomPlace(room)
        this.drawTile(context, 'menu_map_room', x, y)
      }
    }
    if (inventory.compasses.includes(level)) {
      const triforce = rooms.find(room => room.room.triforce)
      if (triforce) {
        const { x, y } = roomPlace(triforce)
        const palette = compassPalette(Math.floor(clock.now / FRAME), inventory.triforce.includes(level), map.type)
        this.drawTile(context, `menu_map_dot_${palette}`, x + ROOM_DOT, y)
      }
    }
    if (map.room) {
      const { x, y } = roomPlace(map)
      this.drawTile(context, 'menu_map_dot_link', x + ROOM_DOT, y)
    }
  }

  drawFrame (context, letter, x, item) {
    const y = FRAME_Y
    this.drawTile(context, 'menu_blue_line_corner_north_west', x, y)
    this.drawText(context, letter, SPRITE_TEXT_COLOR_WHITE, x + 8, y)
    this.drawTile(context, 'menu_blue_line_corner_north_east', x + 16, y)
    for (const line of [1, 2]) {
      this.drawTile(context, 'menu_blue_line_vertical', x, y + line * 8)
      this.drawTile(context, 'menu_blue_line_vertical', x + 16, y + line * 8)
    }
    this.drawTile(context, 'menu_blue_line_corner_south_west', x, y + 24)
    this.drawTile(context, 'menu_blue_line_horizontal', x + 8, y + 24)
    this.drawTile(context, 'menu_blue_line_corner_south_east', x + 16, y + 24)
    // The item, 8 pixels wide in the middle of its 16 pixels sprite
    item?.draw(context, (x + 4) * SCALE, (FRAME_ITEM_Y - TOP) * SCALE)
  }

  draw (context) {
    context.fillStyle = 'black'
    context.fillRect(0, 0, 512, 96)

    const map = this.link.map
    const level = MAP_TYPES_LEVELS.indexOf(map?.type) + 1
    if (level > 0) {
      this.drawLevelMap(context, map, level)
    } else if (map) {
      this.drawSurfaceMap(context, map)
    }

    for (const [name, count, y] of COUNTERS) {
      this.drawTile(context, `menu_${name}`, COUNTER_ICON_X, y)
      this.drawText(context, counterText(count(this.link.inventory)), SPRITE_TEXT_COLOR_WHITE, COUNTER_X, y)
    }

    for (const [letter, x, item] of FRAMES) {
      this.drawFrame(context, letter, x, this.link[item])
    }

    this.drawText(context, '-life-', SPRITE_TEXT_COLOR_RED, LIFE_X, 24)
    for (let i = 0; i < this.link.totalLife; i++) {
      const x = HEARTS_X + (i % HEARTS_PER_LINE) * 8
      const y = HEARTS_Y - Math.floor(i / HEARTS_PER_LINE) * 8
      const heart = i < Math.floor(this.link.currentLife + 0.25) ? 'full' : i < this.link.currentLife ? 'half' : 'empty'
      this.drawTile(context, `menu_heart_${heart}`, x, y)
    }
  }
}

export { TopMenu }
