'use strict'

// The beeps of low life, as in the ROM (bank 7 $ED18, in the loop of the game): while Link has one heart or less
// ($066F & $0F = 0: a full heart, half of one), the effect $0604 $40 is asked for every frame; it lasts 19 frames,
// then starts again (measured on the APU: a beep every 19 frames). Measured: it goes on while the screen scrolls, in
// a cave, during its text and while Link holds up an item taken there; it is silent while the inventory is shown
// and on the stairs into a cave (mode $10)
const LOW_LIFE_HEARTS = 1
const BEEP_FRAMES = 19
const FRAME = 1000 / 60

// When the next beep is due ({ next }: a clock time, undefined when silent)
export function createLowLifeBeep () {
  return { next: undefined }
}

// One frame of the game: true when a beep starts now
export function updateLowLifeBeep (beep, life, quiet, now) {
  if (quiet || life <= 0 || life > LOW_LIFE_HEARTS) {
    beep.next = undefined
    return false
  }
  if (beep.next !== undefined && now < beep.next) {
    return false
  }
  beep.next = now + BEEP_FRAMES * FRAME
  return true
}
