'use strict'

import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { chooseDrop, tenthKillByBomb } from '../drop'
import { NES_PIXEL, TILE_WIDTH, DIRECTION_EAST, DIRECTION_WEST, DIRECTION_NORTH, DIRECTION_SOUTH, SOUND_BOSS_HIT, SOUND_ENNEMY_DIE } from '../../constant'
import { Enemy, DIRECTION_VECTORS, DIRECTIONS, STATE_DYING, BODY_INSET, drawImage, pick, randomInt, inset, canWalkTo, reaches, bladeCentre, REACH_BLADE_VERTICAL, REACH_BLADE_SIDEWAYS } from './common'
import { chooseWay } from './walker'
import { slowTick } from '../slow-timers'
import { stopScream } from '../boss-scream'

// The dodongo, read in the ROM (objects $31, $32, bank 4 $98A9; $32 makes a single one), the boss of level 2:
// - it walks on the grid at $20 (half a NES pixel a frame) and turns as the walkers do, facing Link at $20 ($8094,
//   see walker.js); sideways it is 32 NES pixels wide, from its place, and the scenery ahead is looked at from the
//   middle of its body, but going west ($98C8); under x = $20, it goes east;
// - a bomb of Link burning ($AC = $12) less than 16 NES pixels from the front of its mouth ($9A32, tables $99A5:
//   its centre less the one of the bomb, 0 to −16 across going east, 0 to 16 going west, −8 to 8 along, −4 to 4 up
//   or down; the same turned going up or down) is swallowed: it stands still 32 frames, then 64 more full of it,
//   and walks again the frame after ($9900, timers $98BA; measured: 97 frames). The second bomb swallowed kills it:
//   64 frames flashing more, then it dies the frame after, 161 frames after the bomb (measured);
// - a bomb blowing up ($13, $14) less than 12 NES pixels from its centre stuns it ($98F2): its timer $3D starts at
//   $20 and goes down with the slow timers (see slow-timers.js), until 1 (measured: 303 frames, 301 to 310 as the
//   counter of the 10 frames goes). Only the sword
//   held out is then tried on it ($7D29 with the object $0D in its state 2, on either half sideways: no smoke, arrow,
//   flying sword, wand; measured: the smoke does not kill it), and kills it; it leaves a bomb ($50, $51 set to $0A: the kills in a row of a bomb, see
//   drop.js);
// - nothing else hurts it ($F0); touching it takes a heart from Link
const DODONGO = { life: 1, contactDamage: 1 }
const SPEED = 1
const GRID = TILE_WIDTH
const MOUTH_REACH = 16
const MOUTHS = {
  [DIRECTION_EAST]: [[-16, 0], [-4, 4]],
  [DIRECTION_WEST]: [[0, 16], [-4, 4]],
  [DIRECTION_SOUTH]: [[-8, 8], [-16, 0]],
  [DIRECTION_NORTH]: [[-8, 8], [0, 16]]
}
const BLAST_REACH = 12
const SWALLOW_FRAMES = 32
const FULL_FRAMES = 64
const DYING_FRAMES = 64
const STUN_TIMER = 0x20
const STUN_OVER = 1
const DEADLY_BOMBS = 2
const WALK_IMAGE_FRAMES = 8
const STUN_IMAGE_FRAMES = 32
const MAX_TURN_FRAMES = 255
const TURNS = { turnRate: 0x20 }
const LEFT = 0x20
const STATE_WALKING = 'walking'
const STATE_EATING = 'eating'
const STATE_STUNNED = 'stunned'

const isSideways = direction => direction === DIRECTION_EAST || direction === DIRECTION_WEST
const within = (value, [min, max]) => value >= min && value < max

export class Dodongo extends Enemy {
  constructor (type, x, y, random = Math.random) {
    super(type, x, y, DODONGO, random)
    this.direction = pick(random, DIRECTIONS)
    this.turnFrames = randomInt(random, 0, MAX_TURN_FRAMES)
    this.frames = 0
    this.bombs = 0 // Swallowed
    this.phase = 0 // Of the bomb swallowed: swallowing, full, dying
  }

  get bodyWidth () {
    return isSideways(this.direction) ? 2 * TILE_WIDTH : TILE_WIDTH
  }

  // The other weapons go by it (see isHitByBlade)
  get isVulnerable () {
    return false
  }

  getBox () {
    return inset(this.x, this.y, this.bodyWidth, this.height, BODY_INSET)
  }

  start (map) {
    this.setState(STATE_WALKING)
    const free = DIRECTIONS.filter(direction => this.canGo(map, direction))
    if (free.length > 0) {
      this.direction = pick(this.random, free)
    }
  }

  // The scenery ahead, from the middle of its body but going west
  canGo (map, direction) {
    return canWalkTo(map, this.x + (direction === DIRECTION_WEST ? 0 : TILE_WIDTH), this.y, direction)
  }

  // The way blocked: a quarter turn one side or the other at random, then the other side, then back (bank 7, $F1DF)
  avoidObstacle (map) {
    if (this.canGo(map, this.direction)) {
      return true
    }
    const side = pick(this.random, isSideways(this.direction) ? [DIRECTION_NORTH, DIRECTION_SOUTH] : [DIRECTION_EAST, DIRECTION_WEST])
    const opposite = { [DIRECTION_EAST]: DIRECTION_WEST, [DIRECTION_WEST]: DIRECTION_EAST, [DIRECTION_NORTH]: DIRECTION_SOUTH, [DIRECTION_SOUTH]: DIRECTION_NORTH }
    for (const direction of [side, opposite[side], opposite[this.direction]]) {
      if (this.canGo(map, direction)) {
        this.direction = direction
        return true
      }
    }
    return false
  }

  // Only the sword hurts it (see isHitByBlade)
  hit () {}

  // The sword held out kills it stunned
  hitByBlade (link) {
    this.lastSwing = link.swordSwing
    tenthKillByBomb(link.killRecord)
    this.die(link, true)
  }

  // The boomerang does nothing to it
  stun () {}

  // Killed by the sword (counted as a kill, see drop.js), or of its second bomb
  die (link, bySword) {
    soundManager.play(resource.getSound(SOUND_BOSS_HIT))
    soundManager.play(resource.getSound(SOUND_ENNEMY_DIE))
    // Its scream is cut ($9955, $B010: $0603 $80)
    stopScream()
    this.drop = chooseDrop(this.type, link.killRecord, this.random, bySword, this.slot, bySword)
    this.setState(STATE_DYING)
  }

  // Stunned, the sword reaches either half of it sideways ($9967); not the wand
  isHitByBlade (link) {
    const blade = link.getBlade()
    if (!blade || blade.wand || this.state !== STATE_STUNNED || link.swordSwing === this.lastSwing) {
      return false
    }
    const centre = bladeCentre(blade.x, blade.y, link.direction)
    const thresholds = blade.vertical ? REACH_BLADE_VERTICAL : REACH_BLADE_SIDEWAYS
    return reaches(this, ...centre, thresholds) || (isSideways(this.direction) && reaches({ x: this.x + TILE_WIDTH, y: this.y }, ...centre, thresholds))
  }

  process (map, link) {
    this.frames++
    super.process(map, link)
    if (this.isActive) {
      this.lookAtBombs(map)
    }
  }

  act (map, link) {
    switch (this.state) {
      case STATE_WALKING:
        this.walk(map, link)
        break
      case STATE_EATING:
        this.eat(link)
        break
      case STATE_STUNNED:
        if (slowTick()) {
          this.stunTimer--
        }
        if (this.stunTimer <= STUN_OVER) {
          this.setState(STATE_WALKING)
        }
        break
    }
  }

  walk (map, link) {
    if (this.turnFrames > 0) {
      this.turnFrames--
    }
    for (let i = 0; i < SPEED; i++) {
      if ((this.x - map.x) % GRID === 0 && (this.y - map.y) % GRID === 0) {
        chooseWay(this, map.target ?? link, TURNS)
        if (!this.avoidObstacle(map)) {
          return
        }
      }
      const [dx, dy] = DIRECTION_VECTORS[this.direction]
      this.x += dx
      this.y += dy
      if ((this.x - map.x) / NES_PIXEL < LEFT) {
        this.direction = DIRECTION_EAST
      }
    }
  }

  // Swallowing a bomb, full of it, then dying of the second one; it walks again or dies a frame after its last phase
  eat (link) {
    const last = this.phase === 2 || (this.phase === 1 && this.bombs < DEADLY_BOMBS)
    const frames = [SWALLOW_FRAMES, FULL_FRAMES, DYING_FRAMES][this.phase] + (last ? 1 : 0)
    if (this.steps < frames) {
      return
    }
    this.phase++
    this.steps = 0
    if (this.phase === 2 && this.bombs < DEADLY_BOMBS) {
      this.setState(STATE_WALKING)
    } else if (this.phase === 3) {
      this.die(link, false)
    }
  }

  // Link's bombs: one burning before its mouth is swallowed, one blowing up by it stuns it ($99B9)
  lookAtBombs (map) {
    const x = this.x + (isSideways(this.direction) ? 16 : 8) * NES_PIXEL
    const y = this.y + 8 * NES_PIXEL
    for (const bomb of map.bombs) {
      if (bomb.done) {
        continue
      }
      const dx = (x - bomb.x) / NES_PIXEL - 8
      const dy = (y - bomb.y) / NES_PIXEL - 8
      if (!bomb.isExploding) {
        const [across, along] = MOUTHS[this.direction]
        const near = within(dx, [-MOUTH_REACH, MOUTH_REACH + 1]) && within(dy, [-MOUTH_REACH, MOUTH_REACH + 1])
        if (near && within(dx, across) && within(dy, along) && this.state !== STATE_STUNNED) {
          bomb.done = true
          this.swallow()
        }
      } else if (within(dx, [-BLAST_REACH, BLAST_REACH]) && within(dy, [-BLAST_REACH, BLAST_REACH]) && this.state !== STATE_STUNNED) {
        // Its timer ($3D) goes on: stunned again only once it walks
        this.stunNow()
      }
    }
  }

  // Its timer $3D at $20
  stunNow () {
    this.setState(STATE_STUNNED)
    this.stunTimer = STUN_TIMER
  }

  // Swallowed walking, it stops; already full, it is stunned
  swallow () {
    if (this.state === STATE_EATING) {
      this.stunNow()
      return
    }
    this.bombs++
    this.phase = 0
    this.setState(STATE_EATING)
  }

  drawBody (context) {
    const width = this.bodyWidth
    if (this.state === STATE_EATING && this.phase === 1) {
      drawImage(context, resource.getSprite(`dodongo_${this.direction}_full`), 0, this.x, this.y, width, this.height)
      return
    }
    // Flashing before it dies: drawn 2 frames out of 4
    if (this.state === STATE_EATING && this.phase === 2 && !(this.frames & 2)) {
      return
    }
    const frames = this.state === STATE_STUNNED ? STUN_IMAGE_FRAMES : WALK_IMAGE_FRAMES
    const image = this.state === STATE_EATING && this.phase === 2 ? 0 : Math.floor(this.frames / frames) % 2
    drawImage(context, resource.getSprite(`dodongo_${this.direction}_move`), image, this.x, this.y, width, this.height)
  }
}
