'use strict'

import worldManager from '../service/world-manager'
import { createBItem } from './link'
import { Inventory } from './inventory'
import { MAP_TYPES, MAP_TYPE_WORLD, SECRET_ARMOS, SECRET_WHISTLE, ITEM_RING_GREEN } from '../constant'

// The three games of the cartridge, as the ROM keeps them in its RAM (see docs/rom-analysis.md, Sauvegarde): a name of
// 8 letters, whether it is registered, the deaths, the items and the flags of the screens. Kept in the browser, as the
// battery keeps the RAM of the cartridge
export const SLOTS = 3
export const NAME_LENGTH = 8
const STORAGE_KEY = 'loz-saves'
// A game starts and starts again with 3 hearts: a new one ($066F = $22 at the registration), and a saved one (the game
// over menu leaves 3 full hearts, $066F low digit 2, before SAVE copies the items, measured)
export const START_LIFE = 3

// The hidden entrances that stay open (bit 7 of the flags of a screen); an Armos and the lake are back at each visit
const LASTING_SECRETS = tile => tile.revealed && tile.destructible !== SECRET_ARMOS && tile.destructible !== SECRET_WHISTLE

export function emptySlot () {
  return { registered: false, name: ' '.repeat(NAME_LENGTH), deaths: 0, game: undefined }
}

// The three games kept, or empty ones (none yet, storage unavailable or unreadable). A game that is not one is erased,
// as the ROM erases a game whose checksum is wrong
export function readSlots (storage = globalThis.localStorage) {
  let saved
  try {
    saved = JSON.parse(storage?.getItem(STORAGE_KEY) ?? 'null')
  } catch (e) {
    saved = undefined
  }
  return Array.from({ length: SLOTS }, (_, i) => {
    const slot = saved?.slots?.[i]
    if (!slot || typeof slot.name !== 'string' || typeof slot.deaths !== 'number') {
      return emptySlot()
    }
    return { registered: !!slot.registered, name: slot.name.padEnd(NAME_LENGTH).slice(0, NAME_LENGTH), deaths: slot.deaths, game: slot.game ?? undefined }
  })
}

export function writeSlots (slots, storage = globalThis.localStorage) {
  try {
    storage?.setItem(STORAGE_KEY, JSON.stringify({ slots }))
  } catch (e) {
    // Storage unavailable (private browsing, blocked site data): the games only last for the session
  }
}

// What the choice of the game shows of it: its hearts (the containers, all full) and the colour of Link's ring
export function slotHearts (slot) {
  return slot.game?.totalLife ?? START_LIFE
}

export function slotRing (slot) {
  return slot.game?.inventory?.ring ?? ITEM_RING_GREEN
}

// The flags of a map that last: the doors opened, the room visited, the cave or room emptied, the item of the room
// taken, the boss killed (bits 6-7 of its room, $C0), the hidden entrances found, and on a screen of the surface the
// count of its enemies killed (its 3 low bits, measured: SAVE keeps it, and fewer come back after loading)
function mapFlags (map) {
  const flags = {}
  if (map.openSides.size > 0) {
    flags.open = [...map.openSides]
  }
  if (map.type === MAP_TYPE_WORLD && map.killed > 0) {
    flags.killed = map.killed
  }
  for (const key of ['visited', 'emptied', 'itemTaken', 'bossKilled']) {
    if (map[key]) {
      flags[key] = true
    }
  }
  const revealed = [...map.tilesIterator()].filter(LASTING_SECRETS).map(tile => [tile.column, tile.line])
  if (revealed.length > 0) {
    flags.revealed = revealed
  }
  return flags
}

// What SAVE copies (bank 2, $A6B8): the items ($0657-$067E) and the flags of the screens and rooms ($067F-$07FE)
export function snapshotGame (link) {
  const maps = {}
  for (const type of MAP_TYPES) {
    for (const map of worldManager.mapsIterator(type)) {
      const flags = mapFlags(map)
      if (Object.keys(flags).length > 0) {
        maps[`${type} ${map.column} ${map.line}`] = flags
      }
    }
  }
  return {
    inventory: structuredClone({ ...link.inventory }),
    totalLife: link.totalLife,
    swords: link.items.map(item => item.name),
    sword: link.itemA?.name,
    maps
  }
}

// A saved game taken back (bank 2, $A5FE): its items and its flags on the maps just made. Link has 3 hearts, and B the
// first of his items ($0656 = 0)
export function restoreGame (game, link) {
  const known = new Inventory()
  for (const key of Object.keys(known)) {
    if (game.inventory?.[key] !== undefined) {
      link.inventory[key] = structuredClone(game.inventory[key])
    }
  }
  link.totalLife = game.totalLife ?? START_LIFE
  link.currentLife = Math.min(START_LIFE, link.totalLife)
  link.items = (game.swords ?? []).map(name => createBItem(name))
  const sword = link.items.find(item => item.name === game.sword)
  if (sword) {
    link.itemA = sword
  }
  link.equipB(link.inventory.bItems.find(Boolean))
  for (const [key, flags] of Object.entries(game.maps ?? {})) {
    const [type, column, line] = key.split(' ')
    const map = worldManager.getMap(type, Number(column), Number(line))
    if (!map) {
      continue
    }
    map.openSides = new Set(flags.open ?? [])
    map.visited = !!flags.visited
    map.emptied = !!flags.emptied
    map.itemTaken = !!flags.itemTaken
    map.bossKilled = !!flags.bossKilled
    if (map.type === MAP_TYPE_WORLD) {
      map.killed = Number.isInteger(flags.killed) ? Math.min(Math.max(flags.killed, 0), 7) : 0
    }
    for (const [tileColumn, tileLine] of flags.revealed ?? []) {
      map.getTile(tileColumn, tileLine)?.reveal()
    }
  }
}
